### __tests__/acceptance/m7.test.ts
```ts
import { createStore, createMemoryRawStore, createMemoryKeyProvider } from '../../src/lib/storage/memory';
import { addReceipt, getAllReceipts } from '../../src/lib/receiptStore';
import {
  getAllCategories,
  renameCategory,
  isCategoryInUse,
  syncCategoriesWithReceipts,
} from '../../src/lib/categories';
import { addMileageEntry, getAllMileageEntries } from '../../src/lib/mileageStore';
import { calculateMileageDeduction } from '../../src/lib/mileage';

describe('M7: rename category updates receipts', () => {
  it('updates receipt categories when a category is renamed', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    // Add a receipt that uses the default category "Meals"
    const receipt = {
      id: 'r1',
      amount: 50,
      date: '2023-04-01',
      category: 'Meals',
      type: 'expense',
      notes: '',
    };
    await addReceipt(store, receipt);

    // Verify the receipt initially has the old category
    let receipts = await getAllReceipts(store);
    expect(receipts).toHaveLength(1);
    expect(receipts[0].category).toBe('Meals');

    // Perform the rename
    await renameCategory(store, 'Meals', 'Food & Dining');

    // Verify the receipt category was updated
    receipts = await getAllReceipts(store);
    expect(receipts[0].category).toBe('Food & Dining');

    // Verify the category list reflects the rename
    const categories = await getAllCategories(store);
    expect(categories.some(c => c.name === 'Meals')).toBe(false);
    expect(categories.some(c => c.name === 'Food & Dining')).toBe(true);

    // isCategoryInUse should now be true for the new name
    const inUse = await isCategoryInUse(store, 'Food & Dining');
    expect(inUse).toBe(true);

    // syncCategoriesWithReceipts must not resurrect the old name
    await syncCategoriesWithReceipts(store);
    const postSyncCategories = await getAllCategories(store);
    expect(postSyncCategories.some(c => c.name === 'Meals')).toBe(false);
    expect(postSyncCategories.some(c => c.name === 'Food & Dining')).toBe(true);
  });
});

describe('M7: mileage entry accepts decimal miles', () => {
  it('stores a mileage entry with a fractional mile value and calculates deduction correctly', async () => {
    const store = createStore(createMemoryRawStore(), createMemoryKeyProvider());

    const entry = {
      id: 'm1',
      date: '2023-05-01',
      miles: 12.5,
      purpose: 'Client site visit',
    };

    await addMileageEntry(store, entry);
    const entries = await getAllMileageEntries(store);
    expect(entries).toHaveLength(1);
    expect(entries[0].miles).toBeCloseTo(12.5, 2);

    const rate = 0.585; // Default IRS rate
    const expectedDeduction = 12.5 * rate;
    const deduction = calculateMileageDeduction(entry.miles, rate);
    expect(deduction).toBeCloseTo(expectedDeduction, 5);
  });
});
```

